/**
 * Offline shell cache + navigation fallback.
 * Generated by scripts/generate-service-worker.mjs — do not edit public/sw.js directly.
 */
const BUILD_ID = '__BUILD_ID__';
const PRECACHE_CACHE = `vt-offline-precache-${BUILD_ID}`;
const RUNTIME_CACHE = `vt-offline-runtime-${BUILD_ID}`;
const OFFLINE_URL = '/offline.html';
const PRECACHE_URLS = [OFFLINE_URL];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(PRECACHE_CACHE).then((cache) => cache.addAll(PRECACHE_URLS)),
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) =>
      Promise.all(
        cacheNames
          .filter((cacheName) => cacheName !== PRECACHE_CACHE && cacheName !== RUNTIME_CACHE)
          .map((cacheName) => caches.delete(cacheName)),
      ),
    ),
  );
  self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') {
    return;
  }
  const requestUrl = new URL(request.url);
  if (requestUrl.origin !== self.location.origin) {
    return;
  }
  if (requestUrl.pathname.startsWith('/_next/static/')) {
    event.respondWith(cacheStaticAsset(request));
    return;
  }
  if (request.mode === 'navigate') {
    event.respondWith(fetchNavigationDocument(request));
  }
});

/**
 * @param {Request} request
 * @returns {Promise<Response>}
 */
async function cacheStaticAsset(request) {
  const cache = await caches.open(RUNTIME_CACHE);
  const cachedResponse = await cache.match(request);
  if (cachedResponse) {
    return cachedResponse;
  }
  const networkResponse = await fetch(request);
  if (networkResponse.ok) {
    await cache.put(request, networkResponse.clone());
  }
  return networkResponse;
}

/**
 * @param {Response} response
 * @returns {boolean}
 */
function shouldPassThroughNavigationResponse(response) {
  if (response.ok) {
    return true;
  }
  // Redirects (e.g. /auth/sign-out) and HTTP error pages must not map to offline.html.
  return response.status >= 300;
}

/**
 * @param {Request} request
 * @returns {Promise<Response>}
 */
async function fetchNavigationDocument(request) {
  try {
    const networkResponse = await fetch(request);
    if (shouldPassThroughNavigationResponse(networkResponse)) {
      return networkResponse;
    }
  } catch {
    /* Network unavailable */
  }
  const offlineResponse = await caches.match(OFFLINE_URL);
  if (offlineResponse) {
    return offlineResponse;
  }
  return new Response('Offline', {
    status: 503,
    statusText: 'Service Unavailable',
    headers: { 'Content-Type': 'text/plain; charset=utf-8' },
  });
}
